<script lang="ts">
  const VALID_STATES = ['novo', 'bom', 'marcas_de_uso', 'danificado', 'manutencao', 'baixado'];
  let { onClose, onSaved }: { onClose: () => void; onSaved: (item: Record<string, unknown>) => void } = $props();
  let form = $state({ categoria: '', marca: '', modelo: '', numeroSerie: '', patrimonio: '', estado: 'bom', observacoes: '' }); let erro = $state(''); let salvando = $state(false);
  async function salvar() { if (!form.categoria.trim()) { erro = 'Categoria é obrigatória.'; return; } salvando = true; try { const response = await fetch('/api/equipamentos/outros', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(form) }); if (response.status === 401) { window.location.assign('/login'); return; } if (!response.ok) { erro = 'Não foi possível cadastrar o item.'; return; } onSaved(await response.json()); } catch { erro = 'Não foi possível cadastrar o item. Tente novamente.'; } finally { salvando = false; } }
</script>
<div class="modal edit-person-modal" role="presentation" onclick={(event) => event.target === event.currentTarget && !salvando && onClose()}><div class="modal__content edit-person-dialog card panel" role="dialog" aria-modal="true" aria-labelledby="other-title"><div class="edit-person-heading"><h2 id="other-title">Adicionar outro item</h2><button class="button--secondary edit-person-close" type="button" onclick={onClose}>×</button></div><form onsubmit={(event) => { event.preventDefault(); salvar(); }}><div class="form-grid">{#each [['categoria','Categoria'],['marca','Marca'],['modelo','Modelo'],['numeroSerie','Número de série'],['patrimonio','Patrimônio']] as field}<div class="form-group"><label for={`other-${field[0]}`}>{field[1]}</label><input id={`other-${field[0]}`} bind:value={form[field[0] as keyof typeof form]} /></div>{/each}<div class="form-group"><label for="other-estado">Estado</label><select id="other-estado" bind:value={form.estado}>{#each VALID_STATES as state}<option value={state}>{state}</option>{/each}</select></div><div class="form-group"><label for="other-observacoes">Observações</label><textarea id="other-observacoes" bind:value={form.observacoes}></textarea></div></div>{#if erro}<p class="form-error" role="alert">{erro}</p>{/if}<footer class="form-actions edit-person-actions"><button class="button--secondary" type="button" onclick={onClose}>Cancelar</button><button class="button--primary" type="submit" disabled={salvando}>Salvar</button></footer></form></div></div>
